  })));
})();

/* ── patch solid (faces) ──────────────────────────────────────────────────── */
const cA = new THREE.Color(0x9fe0d4), cB = new THREE.Color(0xcdeee4);
function faceMat() {
  return new THREE.MeshBasicMaterial({
    vertexColors: true, transparent: true, opacity: 0.58,
    side: THREE.DoubleSide, depthWrite: false
  });
}
function patchGeom(u0, v0, off) {
  const pos = [], col = [], idx = [], c = new THREE.Color();
  for (let i = 0; i <= NU; i++) {
    const tu = i / NU, u = u0 - hu + 2 * hu * tu;
    for (let j = 0; j <= NV; j++) {
      const tv = j / NV, v = v0 - hv + 2 * hv * tv;
      const p = hostP(u, v).add(off);
      pos.push(p.x, p.y, p.z);
      c.copy(cA).lerp(cB, Math.min(1, 0.25 + 0.55 * tu + 0.35 * (1 - tv)));
      col.push(c.r, c.g, c.b);
    }
  }
  for (let i = 0; i < NU; i++) for (let j = 0; j < NV; j++) {
    const a = i * (NV + 1) + j, b = a + NV + 1;
    idx.push(a, b, a + 1, a + 1, b, b + 1);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx); g.computeVertexNormals(); g.computeBoundingSphere();
  return g;
}
function sideGeom(loop, off) {
  const pos = [], col = [], idx = [], n = loop.length;
  for (let i = 0; i < n; i++) {
    const p = loop[i], q = p.clone().add(off);
    pos.push(p.x, p.y, p.z, q.x, q.y, q.z);
    col.push(cA.r, cA.g, cA.b, cB.r, cB.g, cB.b);
  }
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n, a = 2 * i, b = 2 * i + 1, cc = 2 * j, dd = 2 * j + 1;
    idx.push(a, cc, b, b, cc, dd);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx); g.computeVertexNormals(); g.computeBoundingSphere();
  return g;
}

const botMesh = new THREE.Mesh(new THREE.BufferGeometry(), faceMat());
const topMesh = new THREE.Mesh(new THREE.BufferGeometry(), faceMat());
const sideMesh = new THREE.Mesh(new THREE.BufferGeometry(), faceMat());
[botMesh, topMesh, sideMesh].forEach(m => { m.renderOrder = 1; scene.add(m); });

const edgeSolid = new THREE.LineSegments(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0x12a8a8 }));
const edgeDash = new THREE.LineSegments(new THREE.BufferGeometry(),
  new THREE.LineDashedMaterial({ color: 0x12a8a8, dashSize: 0.10, gapSize: 0.07 }));
edgeSolid.renderOrder = 3; edgeDash.renderOrder = 3;
scene.add(edgeSolid); scene.add(edgeDash);

/* ── sample dot + normal arrow ────────────────────────────────────────────── */
const dot = new THREE.Mesh(new THREE.SphereGeometry(0.075, 20, 14),
  new THREE.MeshBasicMaterial({ color: 0x12a8a8 }));
dot.renderOrder = 4; scene.add(dot);

const shaftGeo = new THREE.CylinderGeometry(0.035, 0.035, 1, 14);
const shaftLo = new THREE.Mesh(shaftGeo, new THREE.MeshBasicMaterial({ color: 0xd9b3e3 }));
const shaftHi = new THREE.Mesh(shaftGeo, new THREE.MeshBasicMaterial({ color: 0xb878c8 }));
shaftLo.renderOrder = 4; shaftHi.renderOrder = 4;
scene.add(shaftLo); scene.add(shaftHi);

const headGeo = new THREE.ConeGeometry(0.135, 0.30, 4);
const nHead = new THREE.Mesh(headGeo, new THREE.MeshBasicMaterial({ color: 0xffffff }));
const nHeadEdge = new THREE.LineSegments(new THREE.EdgesGeometry(headGeo),
  new THREE.LineBasicMaterial({ color: 0xb878c8 }));
nHead.add(nHeadEdge); nHead.renderOrder = 5; scene.add(nHead);

/* ── black flow arrows ────────────────────────────────────────────────────── */
function blackArrow() {
  const g = new THREE.Group();
  const s = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.022, 1, 10),
    new THREE.MeshBasicMaterial({ color: 0x000000 }));
  const h = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.22, 14),
    new THREE.MeshBasicMaterial({ color: 0x000000 }));
  g.add(s); g.add(h); g.userData = { s, h }; scene.add(g); return g;
}
function setBlackArrow(g, base, len) {
  const { s, h } = g.userData;
  const body = Math.max(0.01, len - 0.22);
  s.position.set(0, body / 2, 0); s.scale.set(1, body, 1);
  h.position.set(0, body + 0.11, 0);
  g.position.copy(base);
}
const flowL = blackArrow(), flowR = blackArrow();

/* ── leader arrows ────────────────────────────────────────────────────────── */
function leader(color) {
  const line = new THREE.Line(new THREE.BufferGeometry(),
    new THREE.LineBasicMaterial({ color }));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.18, 14),
    new THREE.MeshBasicMaterial({ color }));
  scene.add(line); scene.add(head);
  return { line, head };
}
const ldArea = leader(0x000000), ldSurf = leader(0x000000), ldCap = leader(0x9a9a9a);
function setLeader(ld, from, to, bend) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const mid = from.clone().addScaledVector(dir, 0.5);
  const perp = new THREE.Vector3().crossVectors(UP, dir);
  if (perp.lengthSq() < 1e-6) perp.set(1, 0, 0);
  mid.addScaledVector(perp.normalize(), bend);
  const pts = new THREE.QuadraticBezierCurve3(from, mid, to).getPoints(36);
  ld.line.geometry.dispose();
  ld.line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  const tip = pts[pts.length - 1], prv = pts[pts.length - 2];
  const d = new THREE.Vector3().subVectors(tip, prv).normalize();
  ld.head.position.copy(tip).addScaledVector(d, -0.09);
  ld.head.quaternion.setFromUnitVectors(UP, d);
}

/* ── fluid particles ──────────────────────────────────────────────────────── */
const PN = 170, TRAV = 2.4;
const pU = new Float32Array(PN), pV = new Float32Array(PN), pS = new Float32Array(PN);
for (let i = 0; i < PN; i++) {
  pU[i] = (Math.random() * 2 - 1) * hu * 0.96;
  pV[i] = (Math.random() * 2 - 1) * hv * 0.96;
  pS[i] = Math.random();
}
const pPos = new Float32Array(PN * 3);
const pGeo = new THREE.BufferGeometry();
pGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3).setUsage(THREE.DynamicDrawUsage));
const particles = new THREE.Points(pGeo, new THREE.PointsMaterial({
  color: 0x1585a8, size: 0.055, transparent: true, opacity: 0.85
}));
particles.renderOrder = 6; scene.add(particles);

/* ── state ────────────────────────────────────────────────────────────────── */
const state = { u0: -0.6, v0: -0.4, speed: 1.2, tilt: 0 };
const target = { ...state };
let playing = true, needsUpdate = true;
let curN = new THREE.Vector3(0, 1, 0), curF = new THREE.Vector3(0, 1, 0);

function orientCyl(mesh, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(1e-4, dir.length());
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  mesh.scale.set(1, len, 1);
}
function pushPoly(arr, pts) {
  for (let i = 0; i < pts.length - 1; i++)
    arr.push(pts[i].x, pts[i].y, pts[i].z, pts[i + 1].x, pts[i + 1].y, pts[i + 1].z);
}

function update() {
  const u0 = state.u0, v0 = state.v0;
  const nC = hostN(u0, v0); curN.copy(nC);
  const tiltR = THREE.MathUtils.degToRad(state.tilt);
  const axis = new THREE.Vector3(0, -0.20 * v0, 1).normalize();
  curF.copy(nC).applyAxisAngle(axis, tiltR).normalize();
  const fDotN = state.speed * Math.cos(tiltR);
  const thick = Math.max(0, fDotN) * 0.4;
  const off = nC.clone().multiplyScalar(thick);

  // faces
  botMesh.geometry.dispose(); botMesh.geometry = patchGeom(u0, v0, new THREE.Vector3());
  topMesh.geometry.dispose(); topMesh.geometry = patchGeom(u0, v0, off);

  // boundary polylines
  const eBack = [], eFront = [], eLeft = [], eRight = [];
  for (let i = 0; i <= NU; i++) {
    const u = u0 - hu + 2 * hu * i / NU;
    eBack.push(hostP(u, v0 - hv)); eFront.push(hostP(u, v0 + hv));
  }
  for (let j = 0; j <= NV; j++) {
    const v = v0 - hv + 2 * hv * j / NV;
    eLeft.push(hostP(u0 - hu, v)); eRight.push(hostP(u0 + hu, v));
  }
  const loop = [];
  eBack.forEach(p => loop.push(p));
  eRight.slice(1).forEach(p => loop.push(p));
  eFront.slice().reverse().slice(1).forEach(p => loop.push(p));
  eLeft.slice().reverse().slice(1, -1).forEach(p => loop.push(p));

  sideMesh.geometry.dispose(); sideMesh.geometry = sideGeom(loop, off);

  const up = a => a.map(p => p.clone().add(off));
  const solid = [], dash = [];
  pushPoly(solid, up(eBack)); pushPoly(solid, up(eFront));
  pushPoly(solid, up(eLeft)); pushPoly(solid, up(eRight));
  pushPoly(solid, eFront); pushPoly(solid, eRight);
  pushPoly(dash, eBack); pushPoly(dash, eLeft);
  const cFR = hostP(u0 + hu, v0 + hv), cBR = hostP(u0 + hu, v0 - hv),
        cFL = hostP(u0 - hu, v0 + hv), cBL = hostP(u0 - hu, v0 - hv);
  [cFR, cBR, cFL].forEach(c => pushPoly(solid, [c, c.clone().add(off)]));
  pushPoly(dash, [cBL, cBL.clone().add(off)]);

  edgeSolid.geometry.dispose();
  edgeSolid.geometry = new THREE.BufferGeometry()
    .setAttribute('position', new THREE.Float32BufferAttribute(solid, 3));
  edgeDash.geometry.dispose();
  const dg = new THREE.BufferGeometry()
    .setAttribute('position', new THREE.Float32BufferAttribute(dash, 3));
  edgeDash.geometry = dg; edgeDash.computeLineDistances();

  // sample dot + normal arrow
  const P0 = hostP(u0, v0);
  dot.position.copy(P0);
  const L = 1.6, tip = P0.clone().addScaledVector(nC, L);
  orientCyl(shaftLo, P0, P0.clone().addScaledVector(nC, L * 0.5));
  orientCyl(shaftHi, P0.clone().addScaledVector(nC, L * 0.5),
                     P0.clone().addScaledVector(nC, L - 0.28));
  nHead.position.copy(tip).addScaledVector(nC, -0.15);
  nHead.quaternion.setFromUnitVectors(UP, nC);

  // black flow arrows just outside the lower corners
  const aL = hostP(u0 - hu - 0.40, v0 + hv * 0.75);
  const aR = hostP(u0 + hu + 0.40, v0 + hv * 0.75);
  setBlackArrow(flowL, new THREE.Vector3(aL.x, aL.y - 0.55, aL.z), 0.9);
  setBlackArrow(flowR, new THREE.Vector3(aR.x, aR.y - 0.55, aR.z), 0.9);

  // leader arrows
  const areaAnchor = new THREE.Vector3(2.30, 2.50, -2.20);
  const surfAnchor = new THREE.Vector3(3.20, 0.90, -1.40);
  const capAnchor  = new THREE.Vector3(0.30, -1.55, 1.30);
  const areaTgt = hostP(u0 + hu * 0.55, v0 - hv).add(off).addScaledVector(nC, 0.05);
  const surfTgt = hostP(u0 + hu, v0 + hv * 0.15).addScaledVector(nC, thick * 0.5);
  const capTgt  = hostP(u0 + hu * 0.5, v0 + hv).addScaledVector(nC, -0.18);
  setLeader(ldArea, areaAnchor.clone().add(new THREE.Vector3(-0.15, -0.30, 0.15)), areaTgt, 0.45);
  setLeader(ldSurf, surfAnchor.clone().add(new THREE.Vector3(-0.30, -0.10, 0.20)), surfTgt, 0.30);
  setLeader(ldCap,  capAnchor.clone().add(new THREE.Vector3(0.05, 0.35, -0.05)), capTgt, 0.18);

  // labels
  if (window.__lblN) {
    window.__lblN.pos.copy(tip).addScaledVector(nC, 0.12);
    window.__lblArea.pos.copy(areaAnchor);
    window.__lblSurf.pos.copy(surfAnchor);
    window.__lblCap.pos.copy(capAnchor);
  }

  // readout
  const A = patchArea(u0, v0);
  const ro = document.getElementById('readout');
  if (ro) ro.innerHTML =
    '&Delta;S<sub>k</sub> &asymp; ' + A.toFixed(2) + '<br>' +
    'F&middot;n = ' + fDotN.toFixed(2) + '<br>' +
    '(F&middot;n)&Delta;S<sub>k</sub> &asymp; ' + (fDotN * A).toFixed(2);
}

function updateParticles() {
  const P = new THREE.Vector3();
  for (let i = 0; i < PN; i++) {
    const u = state.u0 + pU[i], v = state.v0 + pV[i];
    P.copy(hostP(u, v)).addScaledVector(curF, pS[i] * TRAV - 1.0);
    pPos[3 * i] = P.x; pPos[3 * i + 1] = P.y; pPos[3 * i + 2] = P.z;
  }
  pGeo.attributes.position.needsUpdate = true;
}

update();
updateParticles();

/* ── camera ───────────────────────────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.6
});

/* ── labels ───────────────────────────────────────────────────────────────── */
window.__lblN = addLabel('<b>n</b>', new THREE.Vector3(),
  { fontSize: '17px', bold: true, offset: [16, -6] });
window.__lblArea = addLabel('Area &Delta;<i>S<sub>k</sub></i>', new THREE.Vector3(),
  { fontSize: '17px', offset: [30, -10] });
window.__lblSurf = addLabel('Surface <i>&sigma;<sub>k</sub></i>', new THREE.Vector3(),
  { fontSize: '17px', offset: [34, 0] });
window.__lblCap = addLabel(
  '<div style="width:250px;white-space:normal;background:#fbe0a8;border:3px solid #9a9a9a;' +
  'border-radius:12px;padding:10px 12px;font:15px/1.35 Georgia,Times,serif;color:#111;' +
  'text-align:left">The volume of fluid crossing <i>&sigma;<sub>k</sub></i> in the direction ' +
  'of <b>n</b> per unit of time.</div>', new THREE.Vector3(), { offset: [0, 40] });
update(); // place labels at their anchors

/* ── hover / click explanations ───────────────────────────────────────────── */
registerInteractive(topMesh, {
  title: 'The swept slab',
  tooltip: 'Drag to move the patch · click to explain',
  body: 'This teal solid is not the surface: it is the fluid that crosses σ_k in one unit of time. Its height is F·n and its base is ΔS_k, so its volume is (F·n)ΔS_k.'
});
registerInteractive(sideMesh, {
  title: 'Side walls of the slab',
  tooltip: 'Drag to move the patch · click to explain',
  body: 'The walls are the patch boundary lofted along n by the distance F·n — the distance a fluid particle travels normal to the surface in unit time.'
});
registerInteractive(nHead, {
  title: 'Unit normal n',
  tooltip: 'The unit normal at the sample point',
  body: 'n is perpendicular to the surface at the sample point (x*_k, y*_k, z*_k). Only the component F·n of the velocity carries fluid through the surface.'
});
registerInteractive(dot, {
  title: 'Sample point (x*_k, y*_k, z*_k)',
  tooltip: 'Sample point on σ_k',
  body: 'F and n are evaluated here; the Riemann sum Σ F·n ΔS_k over all patches becomes the flux integral.'
});

/* ── controls ─────────────────────────────────────────────────────────────── */
const sSpeed = document.getElementById('flowSpeed');
const sTilt = document.getElementById('flowTilt');
const vSpeed = document.getElementById('vSpeed');
const vTilt = document.getElementById('vTilt');
const btnPlay = document.getElementById('btnPlay');

sSpeed.addEventListener('input', () => {
  target.speed = state.speed = parseFloat(sSpeed.value); needsUpdate = true;
});
sTilt.addEventListener('input', () => {
  target.tilt = state.tilt = parseFloat(sTilt.value); needsUpdate = true;
});
btnPlay.addEventListener('click', () => {
  playing = !playing;
  btnPlay.innerHTML = playing ? '&#9208; Pause fluid flow' : '&#9654; Play fluid flow';
  btnPlay.classList.toggle('active', !playing);
});
document.getElementById('btnResetPatch').addEventListener('click', () => {
  target.u0 = -0.6; target.v0 = -0.4;
});

function syncUI() {
  sSpeed.value = state.speed.toFixed(1);
  sTilt.value = Math.round(state.tilt / 5) * 5;
  vSpeed.textContent = state.speed.toFixed(1);
  vTilt.textContent = Math.round(state.tilt);
}
syncUI();

/* ── demo steps ───────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The patch and its normal',
    text: 'A small curved tile σ_k of area ΔS_k is cut from the surface, with the unit normal n erected at the sample point. The teal slab above it is the fluid that will cross in one unit of time.',
    s: { speed: 1.2, tilt: 0, u0: -0.6, v0: -0.4 } },
  { title: 'Faster flow, bigger volume',
    text: 'Increasing the flow speed thickens the slab proportionally: the volume crossing per unit time is (F·n)ΔS_k, linear in |F|.',
    s: { speed: 2.6, tilt: 0, u0: -0.6, v0: -0.4 } },
  { title: 'Tilting the flow',
    text: 'Tilting F away from n keeps the speed the same but shrinks the slab — at 90° the fluid slides along the surface and nothing crosses it.',
    s: { speed: 2.6, tilt: 75, u0: -0.6, v0: -0.4 } },
  { title: 'Move the patch',
    text: 'The patch slides to a new place on the host surface: n swings to the new outward direction and ΔS_k updates, which is why the flux must be summed patch by patch.',
    s: { speed: 1.6, tilt: 0, u0: 1.5, v0: 1.0 } }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  Object.assign(target, st.s);
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + st.title;
  document.getElementById('stepText').textContent = st.text;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);
Object.assign(state, STEPS[0].s);

/* ── drag the patch across the host surface ───────────────────────────────── */
const rc = new THREE.Raycaster(), ptr = new THREE.Vector2();
let dragging = false;
const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
function setPtr(e) {
  const r = canvas.getBoundingClientRect();
  ptr.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ptr.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', e => {
  setPtr(e); rc.setFromCamera(ptr, camera);
  const hit = rc.intersectObjects([topMesh, botMesh, sideMesh, dot, shaftLo, shaftHi, nHead], false);
  if (hit.length) { dragging = true; controls.enabled = false; }
});
canvas.addEventListener('pointermove', e => {
  if (!dragging) return;
  setPtr(e); rc.setFromCamera(ptr, camera);
  const hit = rc.intersectObject(window.__hostMesh, false);
  if (hit.length) {
    const p = hit[0].point;
    target.u0 = state.u0 = clamp(p.x, -HX + hu + 0.15, HX - hu - 0.15);
    target.v0 = state.v0 = clamp(p.z, -HZ + hv + 0.15, HZ - hv - 0.15);
    needsUpdate = true;
  }
});
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; }
});

/* ── own update loop (tweening + particle advection) ──────────────────────── */
let _last = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000); _last = now;

  let moving = false;
  for (const k of ['u0', 'v0', 'speed', 'tilt']) {
    const dv = target[k] - state[k];
    if (Math.abs(dv) > 1e-4) { state[k] += dv * Math.min(1, dt * 5); moving = true; }
    else state[k] = target[k];
  }
  if (moving || needsUpdate) { update(); syncUI(); needsUpdate = false; }

  if (playing) {
    const adv = Math.max(0.12, state.speed) * dt / TRAV;
    for (let i = 0; i < PN; i++) { pS[i] += adv; if (pS[i] > 1) pS[i] -= 1; }
    updateParticles();
  }
}
tick();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

