  new THREE.ShapeGeometry(new THREE.Shape(calPts2)),
  new THREE.MeshBasicMaterial({
    color: 0xfbe0a8, side: THREE.DoubleSide,
    transparent: true, opacity: 0.97, depthWrite: false
  }));
calMesh.add(new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints(calPts2.map(p => new THREE.Vector3(p.x, p.y, 0))),
  new THREE.LineBasicMaterial({ color: 0x9a9a9a })));
calMesh.renderOrder = 1;
scene.add(calMesh);

/* ── faint host surface (hidden by default) ───────────────────────────────── */
const hostGroup = new THREE.Group();
hostGroup.visible = false;
(function buildHost() {
  const nu = 26, nv = 20, pos = [], idx = [];
  for (let i = 0; i <= nu; i++) for (let j = 0; j <= nv; j++) {
    const u = -HX + 2 * HX * i / nu, v = -HZ + 2 * HZ * j / nv;
    const p = hostP(u, v); pos.push(p.x, p.y, p.z);
  }
  for (let i = 0; i < nu; i++) for (let j = 0; j < nv; j++) {
    const a = i * (nv + 1) + j, b = a + nv + 1;
    idx.push(a, b, a + 1, a + 1, b, b + 1);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx); g.computeVertexNormals();
  hostGroup.add(new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color: 0x7fd0c4, transparent: true, opacity: 0.07,
    side: THREE.DoubleSide, depthWrite: false
  })));
  const seg = [], LU = 8, LV = 6, S = 40;
  for (let i = 0; i <= LU; i++) {
    const u = -HX + 2 * HX * i / LU;
    for (let k = 0; k < S; k++) {
      const p1 = hostP(u, -HZ + 2 * HZ * k / S), p2 = hostP(u, -HZ + 2 * HZ * (k + 1) / S);
      seg.push(p1.x, p1.y, p1.z, p2.x, p2.y, p2.z);
    }
  }
  for (let j = 0; j <= LV; j++) {
    const v = -HZ + 2 * HZ * j / LV;
    for (let k = 0; k < S; k++) {
      const p1 = hostP(-HX + 2 * HX * k / S, v), p2 = hostP(-HX + 2 * HX * (k + 1) / S, v);
      seg.push(p1.x, p1.y, p1.z, p2.x, p2.y, p2.z);
    }
  }
  const wg = new THREE.BufferGeometry();
  wg.setAttribute('position', new THREE.Float32BufferAttribute(seg, 3));
  hostGroup.add(new THREE.LineSegments(wg, new THREE.LineBasicMaterial({
    color: 0x3fb8b0, transparent: true, opacity: 0.18
  })));
})();

/* ── fluid particles (hidden by default) ──────────────────────────────────── */
const PN = 160, TRAV = 2.2;
const pU = new Float32Array(PN), pV = new Float32Array(PN), pS = new Float32Array(PN);
for (let i = 0; i < PN; i++) {
  pU[i] = (Math.random() * 2 - 1) * hu * 0.94;
  pV[i] = (Math.random() * 2 - 1) * hv * 0.94;
  pS[i] = Math.random();
}
const pPos = new Float32Array(PN * 3);
const pGeo = new THREE.BufferGeometry();
pGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3).setUsage(THREE.DynamicDrawUsage));
const particles = new THREE.Points(pGeo, new THREE.PointsMaterial({
  color: 0x1585a8, size: 0.055, transparent: true, opacity: 0.85
}));
particles.visible = false; particles.renderOrder = 8; scene.add(particles);

/* ── state ────────────────────────────────────────────────────────────────── */
const state = { u0: 0, v0: 0, speed: 1.5, tilt: 0 };
const target = { ...state };
let flowOn = false, needsUpdate = true;
const curN = new THREE.Vector3(0, 1, 0), curF = new THREE.Vector3(0, 1, 0);

const anchors = {
  area: new THREE.Vector3(2.0, 1.9, -0.9),
  surf: new THREE.Vector3(2.3, 0.4, 0.5),
  cap: new THREE.Vector3(-0.8, -1.7, 1.1),
  calTail: new THREE.Vector3(1.4, -1.2, 1.4)
};

function orientCyl(mesh, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(1e-4, dir.length());
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  mesh.scale.set(1, len, 1);
}
function pushPoly(arr, pts) {
  for (let i = 0; i < pts.length - 1; i++)
    arr.push(pts[i].x, pts[i].y, pts[i].z, pts[i + 1].x, pts[i + 1].y, pts[i + 1].z);
}

let calTarget = new THREE.Vector3();

function update() {
  const u0 = state.u0, v0 = state.v0;
  const nC = hostN(u0, v0); curN.copy(nC);
  const tiltR = THREE.MathUtils.degToRad(state.tilt);
  const axis = new THREE.Vector3(0, -0.2 * v0, 1).normalize();
  curF.copy(nC).applyAxisAngle(axis, tiltR).normalize();
  const fDotN = state.speed * Math.cos(tiltR);
  const thick = Math.max(0.0, fDotN) * TH;
  const off = nC.clone().multiplyScalar(thick);

  botMesh.geometry.dispose(); botMesh.geometry = patchGeom(u0, v0, new THREE.Vector3());
  topMesh.geometry.dispose(); topMesh.geometry = patchGeom(u0, v0, off);

  const eBack = [], eFront = [], eLeft = [], eRight = [];
  for (let i = 0; i <= NU; i++) {
    const u = u0 - hu + 2 * hu * i / NU;
    eBack.push(hostP(u, v0 - hv)); eFront.push(hostP(u, v0 + hv));
  }
  for (let j = 0; j <= NV; j++) {
    const v = v0 - hv + 2 * hv * j / NV;
    eLeft.push(hostP(u0 - hu, v)); eRight.push(hostP(u0 + hu, v));
  }
  const loop = [];
  eBack.forEach(p => loop.push(p));
  eRight.slice(1).forEach(p => loop.push(p));
  eFront.slice().reverse().slice(1).forEach(p => loop.push(p));
  eLeft.slice().reverse().slice(1, -1).forEach(p => loop.push(p));
  sideMesh.geometry.dispose(); sideMesh.geometry = sideGeom(loop, off);

  const lift = a => a.map(p => p.clone().add(off));
  const solid = [], dash = [];
  pushPoly(solid, lift(eBack)); pushPoly(solid, lift(eFront));
  pushPoly(solid, lift(eLeft)); pushPoly(solid, lift(eRight));
  pushPoly(solid, eFront); pushPoly(solid, eRight);
  pushPoly(dash, eBack); pushPoly(dash, eLeft);
  const cFR = hostP(u0 + hu, v0 + hv), cBR = hostP(u0 + hu, v0 - hv),
    cFL = hostP(u0 - hu, v0 + hv), cBL = hostP(u0 - hu, v0 - hv);
  [cFR, cBR, cFL].forEach(c => pushPoly(solid, [c, c.clone().add(off)]));
  pushPoly(dash, [cBL, cBL.clone().add(off)]);

  edgeSolid.geometry.dispose();
  edgeSolid.geometry = new THREE.BufferGeometry()
    .setAttribute('position', new THREE.Float32BufferAttribute(solid, 3));
  edgeDash.geometry.dispose();
  const dg = new THREE.BufferGeometry()
    .setAttribute('position', new THREE.Float32BufferAttribute(dash, 3));
  edgeDash.geometry = dg; edgeDash.computeLineDistances();

  // sample dot + long normal arrow
  const P0 = hostP(u0, v0);
  dot.position.copy(P0);
  const L = 1.85, tip = P0.clone().addScaledVector(nC, L);
  orientCyl(shaftLo, P0, P0.clone().addScaledVector(nC, Math.max(thick, 0.05)));
  orientCyl(shaftHi, P0.clone().addScaledVector(nC, Math.max(thick, 0.05)),
    P0.clone().addScaledVector(nC, L - 0.38));
  nHead.position.copy(tip).addScaledVector(nC, -0.21);
  nHead.quaternion.setFromUnitVectors(UP, nC);

  // exactly two black flow arrows, at the lower-left and lower-right corners
  const pL = hostP(u0 - hu - 0.10, v0 + hv * 0.95);
  const pR = hostP(u0 + hu - 0.12, v0 + hv + 0.12);
  setBlackArrow(flowL, new THREE.Vector3(pL.x, pL.y - 1.05, pL.z), 1.05);
  setBlackArrow(flowR, new THREE.Vector3(pR.x, pR.y - 1.00, pR.z), 1.00);

  // leader arrows for the two printed labels
  const areaTgt = hostP(u0 + hu * 0.40, v0 - hv).add(off).addScaledVector(nC, 0.03);
  const surfTgt = hostP(u0 + hu, v0 + hv * 0.05).addScaledVector(nC, thick * 0.45);
  setLeader(ldArea, anchors.area.clone().add(new THREE.Vector3(-0.18, -0.30, 0.12)), areaTgt, 0.40);
  setLeader(ldSurf, anchors.surf.clone().add(new THREE.Vector3(-0.30, -0.08, 0.16)), surfTgt, 0.26);

  // where the thick caption arrow points: slab's lower-right edge
  calTarget = hostP(u0 + hu, v0 + hv * 0.75).addScaledVector(nC, thick * 0.3);

  if (window.__lblN) {
    window.__lblN.pos.copy(tip).addScaledVector(nC, 0.16);
    window.__lblArea.pos.copy(anchors.area);
    window.__lblSurf.pos.copy(anchors.surf);
    window.__lblCap.pos.copy(anchors.cap);
  }

  const A = patchArea(u0, v0);
  const ro = document.getElementById('readout');
  if (ro) ro.innerHTML =
    '&Delta;S<sub>k</sub> &asymp; ' + A.toFixed(2) + '<br>' +
    'F&middot;n = ' + fDotN.toFixed(2) + '<br>' +
    '(F&middot;n)&Delta;S<sub>k</sub> &asymp; ' + (fDotN * A).toFixed(2);
}

function updateCallout() {
  const fwd = new THREE.Vector3(); camera.getWorldDirection(fwd);
  const nrm = fwd.clone().negate().normalize();
  const dir = new THREE.Vector3().subVectors(calTarget, anchors.calTail);
  dir.addScaledVector(nrm, -dir.dot(nrm));
  if (dir.lengthSq() < 1e-6) dir.set(1, 0, 0);
  dir.normalize();
  const yA = new THREE.Vector3().crossVectors(nrm, dir).normalize();
  const m = new THREE.Matrix4().makeBasis(dir, yA, nrm);
  calMesh.quaternion.setFromRotationMatrix(m);
  calMesh.position.copy(calTarget).addScaledVector(dir, -(CAL_LEN + 0.08));
}

function updateParticles() {
  const P = new THREE.Vector3();
  for (let i = 0; i < PN; i++) {
    const u = state.u0 + pU[i], v = state.v0 + pV[i];
    P.copy(hostP(u, v)).addScaledVector(curF, pS[i] * TRAV - 0.9);
    pPos[3 * i] = P.x; pPos[3 * i + 1] = P.y; pPos[3 * i + 2] = P.z;
  }
  pGeo.attributes.position.needsUpdate = true;
}

update();
updateParticles();

/* ── camera: frame the slab so it fills the canvas ────────────────────────── */
const VIEW = {
  projection: 'orthographic',
  axisScreenAngles: { x: 12, z: 26 },
  target: [0, 0.35, 0],
  heightFraction: 0.66
};
setCameraView(VIEW);
const LOCK_ZOOM = camera.zoom;
scene.add(hostGroup);                        // added after the fit, so it never inflates it
setCameraView({ ...VIEW, zoom: LOCK_ZOOM });

/* place the label anchors in view-plane coordinates for a source-like layout */
(function placeAnchors() {
  const halfH = camera.top / camera.zoom, halfW = camera.right / camera.zoom;
  const c = controls.target.clone();
  const r = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 0);
  const u = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 1);
  const at = (fx, fy) => c.clone().addScaledVector(r, halfW * fx).addScaledVector(u, halfH * fy);
  anchors.area.copy(at(0.50, 0.78));
  anchors.surf.copy(at(0.60, 0.16));
  anchors.cap.copy(at(-0.34, -0.72));
  anchors.calTail.copy(at(0.26, -0.50));
})();
update();
updateCallout();

/* ── labels ───────────────────────────────────────────────────────────────── */
window.__lblN = addLabel('<b>n</b>', new THREE.Vector3(),
  { fontSize: '20px', bold: true, offset: [20, -4] });
window.__lblArea = addLabel(
  '<span style="font:20px/1.2 Georgia,Times,serif">Area &Delta;<i>S<sub>k</sub></i></span>',
  new THREE.Vector3(), { offset: [34, -12] });
window.__lblSurf = addLabel(
  '<span style="font:20px/1.2 Georgia,Times,serif">Surface <i>&sigma;<sub>k</sub></i></span>',
  new THREE.Vector3(), { offset: [38, 0] });
window.__lblCap = addLabel(
  '<div style="width:300px;white-space:normal;background:#fbe0a8;border:4px solid #a0a0a0;' +
  'border-radius:14px;padding:14px 16px;font:19px/1.45 Georgia,Times,serif;color:#111;' +
  'text-align:left">The volume of fluid crossing <i>&sigma;<sub>k</sub></i> in the direction ' +
  'of <b>n</b> per unit of time.</div>', new THREE.Vector3(), { offset: [0, 0] });
update();

/* ── hover / click explanations ───────────────────────────────────────────── */
registerInteractive(topMesh, {
  title: 'The swept slab',
  tooltip: 'Drag to slide the patch · click to explain',
  body: 'This teal solid is not the surface: it is the fluid that crosses σ_k in one unit of time. Its height is F·n and its base is ΔS_k, so its volume is (F·n)ΔS_k.'
});
registerInteractive(sideMesh, {
  title: 'Side walls of the slab',
  tooltip: 'Drag to slide the patch · click to explain',
  body: 'The walls are the patch boundary lofted along n by the distance F·n — the distance a fluid particle travels normal to the surface in unit time.'
});
registerInteractive(nHead, {
  title: 'Unit normal n',
  tooltip: 'The unit normal at the sample point',
  body: 'n is perpendicular to the surface at the sample point (x*_k, y*_k, z*_k). Only the component F·n of the velocity carries fluid through the surface.'
});
registerInteractive(dot, {
  title: 'Sample point (x*_k, y*_k, z*_k)',
  tooltip: 'Sample point on σ_k',
  body: 'F and n are evaluated here; the Riemann sum Σ F·n ΔS_k over all patches becomes the flux integral ∬ F·n dS.'
});
registerInteractive(flowR, {
  title: 'The flow F',
  tooltip: 'Fluid velocity field',
  body: 'The black arrows show the fluid velocity F arriving at the surface. Only its normal component crosses σ_k.'
});

/* ── controls ─────────────────────────────────────────────────────────────── */
const sSpeed = document.getElementById('flowSpeed');
const sTilt = document.getElementById('flowTilt');
const vSpeed = document.getElementById('vSpeed');
const vTilt = document.getElementById('vTilt');

sSpeed.addEventListener('input', () => {
  target.speed = state.speed = parseFloat(sSpeed.value); needsUpdate = true;
});
sTilt.addEventListener('input', () => {
  target.tilt = state.tilt = parseFloat(sTilt.value); needsUpdate = true;
});
document.getElementById('cbFlow').addEventListener('change', e => {
  flowOn = e.target.checked; particles.visible = flowOn; updateParticles();
});
document.getElementById('cbHost').addEventListener('change', e => {
  hostGroup.visible = e.target.checked;
});
document.getElementById('btnResetPatch').addEventListener('click', () => {
  target.u0 = 0; target.v0 = 0;
});

function syncUI() {
  sSpeed.value = state.speed.toFixed(1);
  sTilt.value = Math.round(state.tilt / 5) * 5;
  vSpeed.textContent = state.speed.toFixed(1);
  vTilt.textContent = Math.round(state.tilt);
}
syncUI();

/* ── guided demo ──────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'The patch and its normal',
    text: 'A small curved tile σ_k of area ΔS_k is cut from the surface and the unit normal n is erected at the sample point. The teal slab above it is the fluid that will cross in one unit of time.',
    s: { speed: 1.5, tilt: 0, u0: 0, v0: 0 }
  },
  {
    title: 'Faster flow, bigger volume',
    text: 'Increasing the flow speed thickens the slab proportionally: the volume crossing per unit time is (F·n)ΔS_k, linear in |F|.',
    s: { speed: 2.8, tilt: 0, u0: 0, v0: 0 }
  },
  {
    title: 'Tilting the flow',
    text: 'Tilting F away from n keeps the speed the same but shrinks the slab — at 90° the fluid slides along the surface and nothing crosses it.',
    s: { speed: 2.8, tilt: 75, u0: 0, v0: 0 }
  },
  {
    title: 'Move the patch',
    text: 'Slide the patch to another place on the surface: n swings to the new outward direction and ΔS_k changes, which is why the flux must be summed patch by patch.',
    s: { speed: 1.6, tilt: 0, u0: 0.95, v0: 0.7 }
  }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  Object.assign(target, st.s);
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + st.title;
  document.getElementById('stepText').textContent = st.text;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── drag the patch along the (analytic) surface ──────────────────────────── */
const rc = new THREE.Raycaster(), ptr = new THREE.Vector2();
let dragging = false;
const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
function setPtr(e) {
  const r = canvas.getBoundingClientRect();
  ptr.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ptr.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
function surfaceHit(e) {
  setPtr(e); rc.setFromCamera(ptr, camera);
  const o = rc.ray.origin, dir = rc.ray.direction;
  if (Math.abs(dir.y) < 1e-4) return null;
  let y = hostH(state.u0, state.v0), p = null;
  for (let k = 0; k < 6; k++) {
    const t = (y - o.y) / dir.y;
    if (!Number.isFinite(t)) return null;
    p = o.clone().addScaledVector(dir, t);
    y = hostH(clamp(p.x, -HX, HX), clamp(p.z, -HZ, HZ));
  }
  return p;
}
canvas.addEventListener('pointerdown', e => {
  setPtr(e); rc.setFromCamera(ptr, camera);
  const hit = rc.intersectObjects([topMesh, botMesh, sideMesh, dot, shaftLo, shaftHi, nHead], false);
  if (hit.length) { dragging = true; controls.enabled = false; }
});
canvas.addEventListener('pointermove', e => {
  if (!dragging) return;
  const p = surfaceHit(e);
  if (p) {
    target.u0 = state.u0 = clamp(p.x, -(HX - hu), HX - hu);
    target.v0 = state.v0 = clamp(p.z, -(HZ - hv), HZ - hv);
    needsUpdate = true;
  }
});
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; }
});

/* ── own loop: tweening, billboard, particle advection ────────────────────── */
let _last = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000); _last = now;

  let moving = false;
  for (const k of ['u0', 'v0', 'speed', 'tilt']) {
    const dv = target[k] - state[k];
    if (Math.abs(dv) > 1e-4) { state[k] += dv * Math.min(1, dt * 5); moving = true; }
    else state[k] = target[k];
  }
  if (moving || needsUpdate) { update(); syncUI(); needsUpdate = false; }
  updateCallout();

  if (flowOn) {
    const adv = Math.max(0.12, state.speed) * dt / TRAV;
    for (let i = 0; i < PN; i++) { pS[i] += adv; if (pS[i] > 1) pS[i] -= 1; }
    updateParticles();
  }
}
tick();
// @FIGURE_CODE_END

