// @FIGURE_CODE_BEGIN
/* ── element spec ───────────────────────────────────────────────────────────
   patch bottom face   → indexed grid BufferGeometry, vertexColors teal→pale, 74%
   patch top face      → same grid rigidly offset by n·thickness (thickness = (F·n)·TH)
   side walls          → strip lofted from the patch boundary loop along n·thickness
   visible edges       → LineSegments  solid  #12a8a8
   hidden back/left    → LineSegments  dashed #12a8a8 (computeLineDistances)
   sample dot          → SphereGeometry(0.10) #0e93a4, depthTest:false (always visible)
   normal shaft        → 2× CylinderGeometry(r .05): inner #e2c6ee, outer #c07fd0
   normal head         → ConeGeometry(.22,.42,4) white fill + EdgesGeometry #b060c8 (hollow)
   flow arrows ×2      → CylinderGeometry(.03)+ConeGeometry(.105,.28), black, along F
   leader arrows ×2    → QuadraticBezierCurve3 Line + ConeGeometry head, black
   caption callout     → ONE billboarded polygon = rounded box + elbow + arrowhead,
                         tan ShapeGeometry fill + grey ribbon outline (always connected)
   host surface        → faint grid mesh + LineSegments (toggle)
   fluid particles     → Points ×160 teal (toggle)
   labels + caption    → addLabel HTML overlays (caption text sits inside the 3D box)
─────────────────────────────────────────────────────────────────────────── */

const UP = new THREE.Vector3(0, 1, 0);
const HX = 2.4, HZ = 1.8;            // host half-spans
const hu = 1.25, hv = 0.85;          // patch half-sizes
const NU = 16, NV = 12;
const TH = 0.50;                     // slab thickness per unit of F·n

/* flatter arch than before – matches the gentle curvature of the printed figure */
const hostH = (u, v) => 0.32 - 0.185 * u * u - 0.07 * v * v;
const hostP = (u, v) => new THREE.Vector3(u, hostH(u, v), v);
const hostN = (u, v) => new THREE.Vector3(0.37 * u, 1, 0.14 * v).normalize();
function patchArea(u0, v0) {
  let A = 0; const N = 20, M = 16, du = 2 * hu / N, dv = 2 * hv / M;
  for (let i = 0; i < N; i++) for (let j = 0; j < M; j++) {
    const u = u0 - hu + (i + 0.5) * du, v = v0 - hv + (j + 0.5) * dv;
    A += Math.sqrt(1 + 0.1369 * u * u + 0.0196 * v * v) * du * dv;
  }
  return A;
}

/* ── patch solid (faces) ──────────────────────────────────────────────────── */
const cBase = new THREE.Color(0x63cdbc), cLite = new THREE.Color(0xeafaf4);
