/* ── the two black flow arrows ────────────────────────────────────────────── */
function blackArrow() {
  const g = new THREE.Group();
  const s = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 1, 10),
    new THREE.MeshBasicMaterial({ color: 0x000000 }));
  const h = new THREE.Mesh(new THREE.ConeGeometry(0.105, 0.28, 16),
    new THREE.MeshBasicMaterial({ color: 0x000000 }));
  g.add(s); g.add(h); g.userData = { s, h }; g.renderOrder = 7; scene.add(g); return g;
}
function setBlackArrow(g, tip, dir, len) {
  const { s, h } = g.userData;
  const body = Math.max(0.01, len - 0.28);
  s.position.set(0, body / 2, 0); s.scale.set(1, body, 1);
  h.position.set(0, body + 0.14, 0);
  g.position.copy(tip).addScaledVector(dir, -len);
  g.quaternion.setFromUnitVectors(UP, dir);
}
const flowL = blackArrow(), flowR = blackArrow();

/* ── two thin black leader arrows for the printed labels ──────────────────── */
function leader(color) {
  const line = new THREE.Line(new THREE.BufferGeometry(),
    new THREE.LineBasicMaterial({ color }));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.21, 14),
    new THREE.MeshBasicMaterial({ color }));
  line.renderOrder = 9; head.renderOrder = 9;
  scene.add(line); scene.add(head);
  return { line, head };
}
const ldArea = leader(0x000000), ldSurf = leader(0x000000);
function setLeader(ld, from, to, bend) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const mid = from.clone().addScaledVector(dir, 0.5);
  const perp = new THREE.Vector3().crossVectors(UP, dir);
  if (perp.lengthSq() < 1e-6) perp.set(1, 0, 0);
  mid.addScaledVector(perp.normalize(), bend);
  const pts = new THREE.QuadraticBezierCurve3(from, mid, to).getPoints(36);
  ld.line.geometry.dispose();
  ld.line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  const tip = pts[pts.length - 1], prv = pts[pts.length - 2];
  const dd = new THREE.Vector3().subVectors(tip, prv).normalize();
  ld.head.position.copy(tip).addScaledVector(dd, -0.11);
  ld.head.quaternion.setFromUnitVectors(UP, dd);
}

/* ── caption callout: box + elbow + head as ONE connected tan polygon ─────── */
const calGroup = new THREE.Group();
const calFill = new THREE.Mesh(new THREE.BufferGeometry(), new THREE.MeshBasicMaterial({
  color: 0xfbe0a8, side: THREE.DoubleSide, transparent: true, opacity: 1, depthWrite: false
}));
const calEdge = new THREE.Mesh(new THREE.BufferGeometry(), new THREE.MeshBasicMaterial({
  color: 0xa3a3a3, side: THREE.DoubleSide, transparent: true, opacity: 1, depthWrite: false
}));
calFill.renderOrder = -3; calEdge.renderOrder = -2;
calGroup.add(calFill); calGroup.add(calEdge);

function ribbonGeom(pts, w) {
  const pos = [], idx = []; let n = 0;
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i], b = pts[(i + 1) % pts.length];
    const dx = b.x - a.x, dy = b.y - a.y, L = Math.hypot(dx, dy) || 1;
    const nx = -dy / L * w, ny = dx / L * w;
    pos.push(a.x + nx, a.y + ny, 0, a.x - nx, a.y - ny, 0,
             b.x + nx, b.y + ny, 0, b.x - nx, b.y - ny, 0);
    idx.push(n, n + 1, n + 2, n + 1, n + 3, n + 2); n += 4;
    pos.push(b.x - w, b.y - w, 0, b.x + w, b.y - w, 0,
             b.x + w, b.y + w, 0, b.x - w, b.y + w, 0);
    idx.push(n, n + 1, n + 2, n, n + 2, n + 3); n += 4;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx); g.computeBoundingSphere();
  return g;
}

let calSig = '';
function buildCallout(W, H, tip, dm) {
  const sig = [W, H, tip.x, tip.y, dm.ct].map(v => v.toFixed(3)).join('|');
  if (sig === calSig) return;
  calSig = sig;
  const bx0 = -W / 2, bx1 = W / 2, by0 = -H / 2, by1 = H / 2;
  const ct = dm.ct, hw = dm.hw, hl = dm.hl;
  let cx = THREE.MathUtils.clamp(bx1 - ct - 0.12 * W, bx0 + ct + 0.02, bx1 - ct - 0.02);
  let cy = Math.max(tip.y, by1 + ct + 0.18);
  let tx = Math.min(tip.x, cx - ct - hl - 0.05);
  const P = (x, y) => new THREE.Vector2(x, y);
  const pts = [
    P(bx0, by0), P(bx1, by0), P(bx1, by1),
    P(cx + ct, by1), P(cx + ct, cy + ct),
    P(tx + hl, cy + ct), P(tx + hl, cy + hw), P(tx, cy),
    P(tx + hl, cy - hw), P(tx + hl, cy - ct),
    P(cx - ct, cy - ct), P(cx - ct, by1), P(bx0, by1)
  ];
  calFill.geometry.dispose();
  calFill.geometry = new THREE.ShapeGeometry(new THREE.Shape(pts));
  calEdge.geometry.dispose();
  calEdge.geometry = ribbonGeom(pts, dm.lw);
}

/* ── faint host surface (hidden by default) ───────────────────────────────── */
const hostGroup = new THREE.Group();
hostGroup.visible = false;
(function buildHost() {
  const nu = 26, nv = 20, pos = [], idx = [];
  for (let i = 0; i <= nu; i++) for (let j = 0; j <= nv; j++) {
    const u = -HX + 2 * HX * i / nu, v = -HZ + 2 * HZ * j / nv;
    const p = hostP(u, v); pos.push(p.x, p.y, p.z);
  }
  for (let i = 0; i < nu; i++) for (let j = 0; j < nv; j++) {
    const a = i * (nv + 1) + j, b = a + nv + 1;
    idx.push(a, b, a + 1, a + 1, b, b + 1);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx); g.computeVertexNormals();
  hostGroup.add(new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color: 0x7fd0c4, transparent: true, opacity: 0.08,
    side: THREE.DoubleSide, depthWrite: false
  })));
  const seg = [], LU = 8, LV = 6, S = 40;
  for (let i = 0; i <= LU; i++) {
    const u = -HX + 2 * HX * i / LU;
    for (let k = 0; k < S; k++) {
      const p1 = hostP(u, -HZ + 2 * HZ * k / S), p2 = hostP(u, -HZ + 2 * HZ * (k + 1) / S);
      seg.push(p1.x, p1.y, p1.z, p2.x, p2.y, p2.z);
    }
  }
  for (let j = 0; j <= LV; j++) {
    const v = -HZ + 2 * HZ * j / LV;
    for (let k = 0; k < S; k++) {
      const p1 = hostP(-HX + 2 * HX * k / S, v), p2 = hostP(-HX + 2 * HX * (k + 1) / S, v);
      seg.push(p1.x, p1.y, p1.z, p2.x, p2.y, p2.z);
    }
  }
  const wg = new THREE.BufferGeometry();
  wg.setAttribute('position', new THREE.Float32BufferAttribute(seg, 3));
  hostGroup.add(new THREE.LineSegments(wg, new THREE.LineBasicMaterial({
    color: 0x3fb8b0, transparent: true, opacity: 0.20
  })));
})();

/* ── fluid particles (hidden by default) ──────────────────────────────────── */
const PN = 160, TRAV = 2.2;
const pU = new Float32Array(PN), pV = new Float32Array(PN), pS = new Float32Array(PN);
for (let i = 0; i < PN; i++) {
  pU[i] = (Math.random() * 2 - 1) * hu * 0.94;
  pV[i] = (Math.random() * 2 - 1) * hv * 0.94;
  pS[i] = Math.random();
}
const pPos = new Float32Array(PN * 3);
const pGeo = new THREE.BufferGeometry();
pGeo.setAttribute('position', new THREE.BufferAttribute(pPos, 3).setUsage(THREE.DynamicDrawUsage));
const particles = new THREE.Points(pGeo, new THREE.PointsMaterial({
  color: 0x1585a8, size: 0.055, transparent: true, opacity: 0.85
}));
particles.visible = false; particles.renderOrder = 8;

/* ── state ────────────────────────────────────────────────────────────────── */
const state = { u0: 0, v0: 0, speed: 1.5, tilt: 0 };
const target = { ...state };
let flowOn = false, needsUpdate = true;
const curN = new THREE.Vector3(0, 1, 0), curF = new THREE.Vector3(0, 1, 0);
let calTarget = new THREE.Vector3();
let slabPts = [];

function orientCyl(mesh, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(1e-4, dir.length());
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
  mesh.scale.set(1, len, 1);
}
function pushPoly(arr, pts) {
  for (let i = 0; i < pts.length - 1; i++)
    arr.push(pts[i].x, pts[i].y, pts[i].z, pts[i + 1].x, pts[i + 1].y, pts[i + 1].z);
}

function update() {
  const u0 = state.u0, v0 = state.v0;
  const nC = hostN(u0, v0); curN.copy(nC);
  const tiltR = THREE.MathUtils.degToRad(state.tilt);
  const axis = new THREE.Vector3().crossVectors(nC, new THREE.Vector3(1, 0, 0)).normalize();
  curF.copy(nC).applyAxisAngle(axis, tiltR).normalize();
  const fDotN = state.speed * Math.cos(tiltR);
  const thick = Math.max(0.0, fDotN) * TH;
  const off = nC.clone().multiplyScalar(thick);

  botMesh.geometry.dispose(); botMesh.geometry = patchGeom(u0, v0, new THREE.Vector3());
  topMesh.geometry.dispose(); topMesh.geometry = patchGeom(u0, v0, off);

  const eBack = [], eFront = [], eLeft = [], eRight = [];
  for (let i = 0; i <= NU; i++) {
    const u = u0 - hu + 2 * hu * i / NU;
    eBack.push(hostP(u, v0 - hv)); eFront.push(hostP(u, v0 + hv));
  }
  for (let j = 0; j <= NV; j++) {
    const v = v0 - hv + 2 * hv * j / NV;
    eLeft.push(hostP(u0 - hu, v)); eRight.push(hostP(u0 + hu, v));
  }
  const loop = [];
  eBack.forEach(p => loop.push(p));
  eRight.slice(1).forEach(p => loop.push(p));
  eFront.slice().reverse().slice(1).forEach(p => loop.push(p));
  eLeft.slice().reverse().slice(1, -1).forEach(p => loop.push(p));
  sideMesh.geometry.dispose(); sideMesh.geometry = sideGeom(loop, off);

  const lift = a => a.map(p => p.clone().add(off));
  const solid = [], dash = [];
  pushPoly(solid, lift(eBack)); pushPoly(solid, lift(eFront));
  pushPoly(solid, lift(eLeft)); pushPoly(solid, lift(eRight));
  pushPoly(solid, eFront); pushPoly(solid, eRight);
  pushPoly(dash, eBack); pushPoly(dash, eLeft);
  const cFR = hostP(u0 + hu, v0 + hv), cBR = hostP(u0 + hu, v0 - hv),
    cFL = hostP(u0 - hu, v0 + hv), cBL = hostP(u0 - hu, v0 - hv);
  [cFR, cBR, cFL].forEach(c => pushPoly(solid, [c, c.clone().add(off)]));
  pushPoly(dash, [cBL, cBL.clone().add(off)]);

  edgeSolid.geometry.dispose();
  edgeSolid.geometry = new THREE.BufferGeometry()
    .setAttribute('position', new THREE.Float32BufferAttribute(solid, 3));
  edgeDash.geometry.dispose();
  const dg = new THREE.BufferGeometry()
    .setAttribute('position', new THREE.Float32BufferAttribute(dash, 3));
  edgeDash.geometry = dg; edgeDash.computeLineDistances();

  slabPts = [cFR, cBR, cFL, cBL,
    cFR.clone().add(off), cBR.clone().add(off),
    cFL.clone().add(off), cBL.clone().add(off),
    hostP(u0, v0 - hv).add(off), hostP(u0, v0 + hv).add(off)];

  // sample dot + long normal arrow
  const P0 = hostP(u0, v0);
  dot.position.copy(P0);
  const L = 1.95, tip = P0.clone().addScaledVector(nC, L);
  const mid = P0.clone().addScaledVector(nC, Math.max(thick, 0.06));
  orientCyl(shaftLo, P0, mid);
  orientCyl(shaftHi, mid, P0.clone().addScaledVector(nC, L - 0.40));
  nHead.position.copy(tip).addScaledVector(nC, -0.21);
  nHead.quaternion.setFromUnitVectors(UP, nC);

  // exactly two black flow arrows, arriving at the slab along F
  const tipL = hostP(u0 - hu - 0.18, v0 + hv + 0.02).add(new THREE.Vector3(0, -0.04, 0));
  const tipR = hostP(u0 + hu - 0.18, v0 + hv + 0.16);
  setBlackArrow(flowL, tipL, curF, 0.95);
  setBlackArrow(flowR, tipR, curF, 0.92);

  // where the thick caption arrow points: slab's right flank
  calTarget = hostP(u0 + hu, v0 + hv * 0.55).addScaledVector(nC, thick * 0.35);

  const A = patchArea(u0, v0);
  const ro = document.getElementById('readout');
  if (ro) ro.innerHTML =
    '&Delta;S<sub>k</sub> &asymp; ' + A.toFixed(2) + '<br>' +
    'F&middot;n = ' + fDotN.toFixed(2) + '<br>' +
    '(F&middot;n)&Delta;S<sub>k</sub> &asymp; ' + (fDotN * A).toFixed(2);

  if (window.__lblN) window.__lblN.pos.copy(tip).addScaledVector(nC, 0.16);
}

function updateParticles() {
  const P = new THREE.Vector3();
  for (let i = 0; i < PN; i++) {
    const u = state.u0 + pU[i], v = state.v0 + pV[i];
    P.copy(hostP(u, v)).addScaledVector(curF, pS[i] * TRAV - 0.9);
    pPos[3 * i] = P.x; pPos[3 * i + 1] = P.y; pPos[3 * i + 2] = P.z;
  }
  pGeo.attributes.position.needsUpdate = true;
}

update();
updateParticles();

