/* ── screen-aware annotation layout (labels, leaders, connected callout) ──── */
function layoutAnnotations() {
  const capE = window.__lblCap;
  if (!capE) return;
  const cw = canvas.clientWidth || 1, ch = canvas.clientHeight || 1;
  const sLbl = (camera.zoom || 1) / (_labelZoomRef || 1);
  const PADpx = 17;
  const bwPx = ((capE.div.offsetWidth || 300) + 2 * PADpx) * sLbl;
  const bhPx = ((capE.div.offsetHeight || 130) + 2 * PADpx) * sLbl;
  const halfH = camera.top / camera.zoom, halfW = camera.right / camera.zoom;
  const viewH = 2 * halfH, px2w = viewH / ch;
  const boxW = bwPx * px2w, boxH = bhPx * px2w;
  const bwN = bwPx / cw, bhN = bhPx / ch;

  const rgt = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 0).normalize();
  const upv = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 1).normalize();
  const ctr = controls.target;
  const toWorld = (nx, ny) => ctr.clone()
    .addScaledVector(rgt, nx * halfW).addScaledVector(upv, ny * halfH);

  let sMaxX = -9, sMinX = 9, sMaxY = -9, sMinY = 9;
  const q = new THREE.Vector3();
  for (const p of slabPts) {
    q.copy(p).project(camera);
    sMaxX = Math.max(sMaxX, q.x); sMinX = Math.min(sMinX, q.x);
    sMaxY = Math.max(sMaxY, q.y); sMinY = Math.min(sMinY, q.y);
  }
  if (!Number.isFinite(sMaxX)) return;

  // "Area ΔS_k" upper-right, "Surface σ_k" to the right — close to the slab
  const aPos = toWorld(Math.min(sMaxX + 0.17, 0.66), Math.min(sMaxY + 0.24, 0.90));
  const sPos = toWorld(Math.min(sMaxX + 0.27, 0.84),
    THREE.MathUtils.clamp((sMinY + sMaxY) / 2 + 0.16, -0.5, 0.62));
  window.__lblArea.pos.copy(aPos);
  window.__lblSurf.pos.copy(sPos);

  const off = curN.clone().multiplyScalar(Math.max(0, state.speed *
    Math.cos(THREE.MathUtils.degToRad(state.tilt))) * TH);
  const areaTgt = hostP(state.u0 + hu * 0.45, state.v0 - hv).add(off);
  const surfTgt = hostP(state.u0 + hu, state.v0 + hv * 0.25).addScaledVector(curN, 0.18);
  const kx = 0.055 * viewH, ky = 0.035 * viewH;
  setLeader(ldArea, aPos.clone().addScaledVector(rgt, -kx).addScaledVector(upv, -ky),
    areaTgt, 0.30);
  setLeader(ldSurf, sPos.clone().addScaledVector(rgt, -kx).addScaledVector(upv, -ky * 0.5),
    surfTgt, 0.22);

  // caption box: bottom of the frame, right edge just past the slab
  const capX = THREE.MathUtils.clamp(sMaxX + 0.10 - bwN, -1 + bwN + 0.02, 1 - bwN - 0.02);
  const capY = -1 + bhN + 0.03;
  const capPos = toWorld(capX, capY);
  capE.pos.copy(capPos);

  calGroup.position.copy(capPos);
  const nrm = new THREE.Vector3().crossVectors(rgt, upv);
  calGroup.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(rgt, upv, nrm));
  const rel = calTarget.clone().sub(capPos);
  buildCallout(boxW, boxH, new THREE.Vector2(rel.dot(rgt), rel.dot(upv)), {
    ct: 0.030 * viewH, hw: 0.076 * viewH, hl: 0.085 * viewH, lw: 0.0055 * viewH
  });
}
update();
layoutAnnotations();

